    ops: @escaping (Int) -> [ReelOp], mixed: (() -> Bool)? = nil,
    enabled: @escaping () -> Bool = { true }, resets: Bool = true
) -> NSView {
    let popup = OptionPopupControl(
        width: width, items: items, read: read,
        write: { [weak binding] index in binding?.apply(name, ops(index)) },
        enabled: enabled,
